134	/** POST /api/cleanup-routines — delete duplicate routines from Hevy */
135	export async function handleCleanupRoutines(env: Env, userId: string): Promise<Response> {
136	  const user = await getUser(env.DB, userId);
137	  if (!user || !user.hevy_api_key) {
138	    return new Response("Connect your Hevy API key first.", { status: 400 });
139	  }
140	
141	  const apiKey = await getDecryptedApiKey(env.DB, userId, env.ENCRYPTION_KEY);
142	  if (!apiKey) {
143	    return new Response("Connect your Hevy API key first.", { status: 400 });
144	  }
145	  const client = new HevyClient(apiKey);
146	  const allRoutines = await client.getAllRoutines();
147	
148	  // Group by title+folder, find duplicates
149	  const byKey = new Map<string, typeof allRoutines>();
150	  for (const r of allRoutines) {
151	    const key = `${r.title}::${r.folder_id ?? "none"}`;
152	    const list = byKey.get(key) ?? [];
153	    list.push(r);
154	    byKey.set(key, list);
155	  }
156	
157	  const toDelete: string[] = [];
158	  for (const [, routines] of byKey) {
159	    if (routines.length > 1) {
160	      // Keep the most recently updated, delete the rest
161	      routines.sort((a, b) => (b.updated_at ?? "").localeCompare(a.updated_at ?? ""));
162	      toDelete.push(...routines.slice(1).map((r) => r.id));
163	    }
164	  }
165	
166	  let deleted = 0;
167	  let failed = 0;
168	  for (const id of toDelete) {
169	    try {
170	      await client.deleteRoutine(id);
171	      deleted++;
172	    } catch {
173	      failed++;
174	    }
175	  }
176	
177	  return new Response(null, { status: 202 });
178	}
