10	/**
11	 * Fetch recent workouts, paging back until every title we're looking for has
12	 * been found (or the page cap is hit). A single page-of-5 fetch isn't deep
13	 * enough once several daily-routine workouts pile up between a session and
14	 * the next sync — the session's workout falls off the window and never
15	 * matches. Bounded to SYNC_MAX_PAGES so a stuck lookup can't page forever.
16	 */
17	export async function fetchWorkoutsCoveringTitles(
18	  client: Pick<HevyClient, "getRecentWorkouts">,
19	  titlesToFind: Set<string>,
20	  usedWorkoutIds: Set<string>
21	): Promise<HevyWorkout[]> {
22	  const all: HevyWorkout[] = [];
23	  const remaining = new Set(titlesToFind);
24	
25	  for (let page = 1; page <= SYNC_MAX_PAGES && remaining.size > 0; page++) {
26	    const batch = await client.getRecentWorkouts(page, SYNC_PAGE_SIZE);
27	    if (batch.length === 0) break;
28	    all.push(...batch);
29	    for (const w of batch) {
30	      if (!usedWorkoutIds.has(w.id)) remaining.delete(w.title);
31	    }
32	    if (batch.length < SYNC_PAGE_SIZE) break;
33	  }
34	
35	  return all;
36	}
