38	/**
39	 * Core sync logic — fetch recent Hevy workouts, match to pending queue items,
40	 * mark completions, update daily CARs. Reused by both manual pull and webhook.
41	 * Updates last_sync_at on successful completion.
42	 */
43	export async function performSync(db: D1Database, userId: string, apiKey: string, tz?: string): Promise<void> {
44	  const { program, programId } = await loadProgram(db, userId);
45	  const routineMap = new Map(program.routines.map((r) => [r.id, r]));
46	  const client = new HevyClient(apiKey);
47	
48	  const items = await getQueueItems(db, userId, programId);
49	
50	  // Skip workouts already matched to a completed queue item
51	  const usedWorkoutIds = new Set<string>(
52	    items.filter((i): i is typeof i & { hevy_workout_id: string } => i.hevy_workout_id != null).map((i) => i.hevy_workout_id)
53	  );
54	
55	  // Matchable items include "skipped" ones too, so a late-arriving workout
56	  // can still retroactively complete an item the user actually did.
57	  const matchableItems = items.filter(
58	    (i) => (i.status === "pending" || i.status === "skipped") && i.hevy_routine_id
59	  );
60	
61	  const nameToRoutineId = new Map<string, string>();
62	  for (const item of matchableItems) {
63	    const routine = routineMap.get(item.routine_id);
64	    if (routine && item.hevy_routine_id) {
65	      nameToRoutineId.set(routine.title, item.hevy_routine_id);
66	    }
67	  }
68	
69	  const dailyRoutine = program.routines.find((r) => r.isDaily);
70	  const titlesToFind = new Set(nameToRoutineId.keys());
71	  if (dailyRoutine) titlesToFind.add(dailyRoutine.title);
72	
73	  const workouts = await fetchWorkoutsCoveringTitles(client, titlesToFind, usedWorkoutIds);
74	  const newWorkouts = workouts.filter((w) => !usedWorkoutIds.has(w.id));
75	
76	  const matches = matchCompletions(
77	    matchableItems,
78	    newWorkouts,
79	    (w) => nameToRoutineId.get(w.title) ?? null
80	  );
81	
82	  // Build workout ID → { date, exercisesJson } map for accurate completion dates
83	  const workoutInfo = new Map<string, { date: string; exercisesJson: string }>();
84	  for (const w of newWorkouts) {
85	    workoutInfo.set(w.id, {
86	      date: toLocalDate(w.start_time, tz),
87	      exercisesJson: JSON.stringify(w.exercises),
88	    });
89	  }
90	
91	  // Batch-mark completions
92	  await batchMarkQueueItemsCompleted(
93	    db,
94	    matches.map((match) => {
95	      const info = workoutInfo.get(match.workoutId);
96	      return {
97	        itemId: match.queueItemId,
98	        completedDate: info?.date ?? todayString(tz),
99	        workoutId: match.workoutId,
100	        workoutData: info?.exercisesJson,
101	      };
102	    })
103	  );
104	
105	  // A completion further down the queue means the user moved past whatever
106	  // was still pending ahead of it — mark those skipped so "Next" advances.
107	  const skippedIds = computeSkippedItemIds(items, matches.map((m) => m.queueItemId));
108	  await batchMarkQueueItemsSkipped(db, skippedIds);
109	
110	  // Check for daily routine completion (use workout date, not sync date)
111	  if (dailyRoutine) {
112	    const dailyWorkout = workouts.find((w) => w.title === dailyRoutine.title);
113	    if (dailyWorkout) {
114	      await updateDailyCompleted(db, userId, toLocalDate(dailyWorkout.start_time, tz));
115	    }
116	  }
117	
118	  await updateLastSyncAt(db, userId, new Date().toISOString());
119	}
