17	/**
18	 * Read and decrypt the Hevy API key for a user.
19	 * Returns null if no key is stored.
20	 * Handles both legacy plaintext values and AES-GCM encrypted values transparently:
21	 * encrypted values contain a colon separator ("base64:base64"); Hevy API keys never do.
22	 */
23	export async function getDecryptedApiKey(
24	  db: D1Database,
25	  userId: string,
26	  encryptionKey: string
27	): Promise<string | null> {
28	  const row = await db
29	    .prepare("SELECT hevy_api_key FROM users WHERE id = ?")
30	    .bind(userId)
31	    .first<{ hevy_api_key: string | null }>();
32	  if (!row?.hevy_api_key) return null;
33	  // Legacy plaintext — Hevy API keys never contain a colon
34	  if (!row.hevy_api_key.includes(":")) {
35	    return row.hevy_api_key;
36	  }
37	  return decryptAesGcm(row.hevy_api_key, encryptionKey);
38	}
